(()=>{let y;ypy.registerExtension("ypy-ptag",{init(t){y=t},ypy_after_init(t){let e=y.attributeValue(t,"ypy-ptag");e&&(y.ypyProp(t).ptag=e)},ypy_config_request(t,{ctx:e}){let p=t._ypy?.ptag;p&&(e.request.headers["YPY-PTag"]=p)},ypy_after_request(t,{ctx:e}){let p=e.response?.headers?.get?.("YPY-PTag");p&&(y.ypyProp(t).ptag=p)}})})();
